begin;
create extension if not exists pgtap with schema extensions;
select extensions.no_plan();
insert into auth.users(id) select ('4b000000-0000-4000-8000-00000000000'||n)::uuid from generate_series(1,4)n;
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) select id,id,'totp','verified',now(),now() from auth.users where id::text like '4b000000-%';
insert into auth.sessions(id,user_id,factor_id,aal) select id,id,id,'aal2' from auth.users where id::text like '4b000000-%';
insert into public.team_profiles(id,full_name) select id,'Synthetic quote staff' from auth.users where id::text like '4b000000-%' and id::text not like '%4';
insert into public.team_role_assignments select ('4b000000-0000-4000-8000-00000000000'||v.n)::uuid,r.id from (values(1,'operations_lead'),(2,'content_community_lead'),(3,'technical_lead'))v(n,code) join public.roles r on r.code=v.code;
insert into business_private.project_requests(id,service_id,service_snapshot,budget_snapshot,full_name,email,whatsapp,requirements,consent_version,idempotency_hash,payload_hash)
 select '4b100000-0000-4000-8000-000000000001',id,'{"title":"Test service"}','{"label":"Small client estimate","minMinor":10,"maxMinor":20}','Synthetic Client','quote@example.invalid','+237600000000','A synthetic quotation project request','test',decode(repeat('4b',32),'hex'),decode(repeat('4c',32),'hex') from public.services order by id limit 1;
-- Fresh databases may have no initialized catalog: provide a fixture first if needed.
insert into public.services(id,slug,title,description,status,accepting_requests) values('4b200000-0000-4000-8000-000000000001','quote-test-fixture','Fixture','Test','published',true);
insert into business_private.project_requests(id,service_id,service_snapshot,full_name,email,whatsapp,requirements,consent_version,idempotency_hash,payload_hash)
 select '4b100000-0000-4000-8000-000000000001','4b200000-0000-4000-8000-000000000001','{"title":"Test service"}','Synthetic Client','quote@example.invalid','+237600000000','A synthetic quotation project request','test',decode(repeat('4b',32),'hex'),decode(repeat('4c',32),'hex') where not exists(select from business_private.project_requests where id='4b100000-0000-4000-8000-000000000001');
create function pg_temp.claims(n integer,aal text default 'aal2') returns text language sql as $$select json_build_object('sub','4b000000-0000-4000-8000-00000000000'||n,'role','authenticated','aal',aal,'session_id','4b000000-0000-4000-8000-00000000000'||n,'exp',extract(epoch from now()+interval '1 hour')::bigint)::text$$;
create function pg_temp.content() returns jsonb language sql as $$select jsonb_build_object('projectDescription','Prepared project description','scope','Agreed scope','deliverables','Approved deliverables','timeline','Three weeks','paymentTerms','Explicit commercial terms','validUntil',(current_date+30)::text,'notes','','exclusions','Hosting excluded','teamAgreement',true,'currency','XAF','items',jsonb_build_array(jsonb_build_object('description','Implementation','quantity',2,'unitAmount',50000)))$$;
create temporary table ids(id uuid);grant all on ids to authenticated;
select extensions.is((select count(*) from public.permissions),27::bigint,'reviewed current permission catalog');
select extensions.is((select count(*) from public.role_permissions),52::bigint,'reviewed current role mappings');
select extensions.ok(not has_function_privilege('anon','public.export_project_request(uuid)','execute'),'anonymous cannot export requests');
select extensions.ok(not has_function_privilege('service_role','public.finalize_quotation(uuid,integer,text,text)','execute'),'privileged ingress has no finalize grant');
select extensions.ok(not has_table_privilege('authenticated','business_private.quotation_revisions','INSERT,UPDATE,DELETE'),'ordinary callers have no direct revision mutations');
select extensions.ok((select relrowsecurity from pg_class where oid='business_private.quotation_revisions'::regclass),'revisions have RLS');
set local role authenticated;
select set_config('request.jwt.claims',pg_temp.claims(1,'aal1'),true);
select extensions.throws_ok($$select public.create_quotation_draft('4b100000-0000-4000-8000-000000000001')$$,'42501',null,'AAL1 cannot prepare quotations');
select set_config('request.jwt.claims',pg_temp.claims(2),true);
select extensions.throws_ok($$select public.create_quotation_draft('4b100000-0000-4000-8000-000000000001')$$,'42501',null,'Content cannot prepare quotations');
select extensions.throws_ok($$select public.export_project_request('4b100000-0000-4000-8000-000000000001')$$,'42501',null,'Content cannot export client data');
select set_config('request.jwt.claims',pg_temp.claims(3),true);
select extensions.throws_ok($$select public.list_request_quotations('4b100000-0000-4000-8000-000000000001')$$,'42501',null,'Technology cannot read financial data');
select set_config('request.jwt.claims',pg_temp.claims(4),true);
select extensions.throws_ok($$select public.create_quotation_draft('4b100000-0000-4000-8000-000000000001')$$,'42501',null,'unassigned AAL2 denied');
select set_config('request.jwt.claims',pg_temp.claims(1),true);
insert into ids select (public.create_quotation_draft('4b100000-0000-4000-8000-000000000001')->>'id')::uuid;
select extensions.is(jsonb_array_length(public.list_request_quotations('4b100000-0000-4000-8000-000000000001')),1,'one draft created');
select extensions.is((public.create_quotation_draft('4b100000-0000-4000-8000-000000000001')->>'id')::uuid,(select id from ids),'creation retry returns same active draft');
select extensions.is((public.get_quotation_revision((select id from ids))->'document'->>'total')::bigint,0::bigint,'client estimate never sets draft price');
select extensions.throws_ok($$select public.finalize_quotation((select id from ids),1,public.get_quotation_revision((select id from ids))->>'digest',repeat('a',64))$$,'22023',null,'incomplete draft cannot finalize');
select extensions.lives_ok($$select public.save_quotation_draft((select id from ids),1,pg_temp.content())$$,'operations can save explicit prices');
select extensions.is((public.get_quotation_revision((select id from ids))->'document'->>'total')::bigint,100000::bigint,'database recomputes integer totals');
select extensions.throws_ok($$select public.save_quotation_draft((select id from ids),1,pg_temp.content())$$,'PT409',null,'stale draft rejected');
select extensions.throws_ok($$select public.save_quotation_draft((select id from ids),2,pg_temp.content()||'{"total":1}')$$,'22023',null,'caller cannot inject a total');
select extensions.throws_ok($$select public.save_quotation_draft((select id from ids),2,jsonb_set(pg_temp.content(),'{items,0,unitAmount}','1.5'))$$,'22023',null,'fractional XAF rejected');
select extensions.throws_ok($$select public.finalize_quotation((select id from ids),2,repeat('0',64),repeat('a',64))$$,'PT409',null,'wrong snapshot digest rejected');
select extensions.throws_ok($$select public.finalize_quotation((select id from ids),null,public.get_quotation_revision((select id from ids))->>'digest',repeat('a',64))$$,'PT409',null,'null optimistic version cannot bypass finalization guard');
reset role;
create function pg_temp.reject_quote_audit() returns trigger language plpgsql as $$begin
 if new.action='quotation.finalized' then raise exception 'Synthetic audit failure'; end if;return new;end;$$;
create trigger reject_quote_audit before insert on public.audit_logs for each row execute function pg_temp.reject_quote_audit();
set local role authenticated;
select extensions.throws_ok($$select public.finalize_quotation((select id from ids),2,public.get_quotation_revision((select id from ids))->>'digest',repeat('a',64))$$,'P0001',null,'failed audit rolls back finalization');
select extensions.is(public.get_quotation_revision((select id from ids))->>'state','draft','failed finalization remains draft');
select extensions.is((public.get_quotation_revision((select id from ids))->>'version')::integer,2,'failed finalization preserves version');
reset role;
select extensions.is((select count(*) from public.audit_logs where action='quotation.finalized' and resource_id=(select id::text from ids)),0::bigint,'failed finalization creates no audit');
drop trigger reject_quote_audit on public.audit_logs;
set local role authenticated;
select extensions.lives_ok($$select public.finalize_quotation((select id from ids),2,public.get_quotation_revision((select id from ids))->>'digest',repeat('a',64))$$,'atomic finalization allowed');
select extensions.throws_ok($$select public.finalize_quotation((select id from ids),2,public.get_quotation_revision((select id from ids))->>'digest',repeat('a',64))$$,'PT409',null,'duplicate finalization cannot create another audit or revision');
select extensions.throws_ok($$select public.save_quotation_draft((select id from ids),3,pg_temp.content())$$,'PT409',null,'finalized revision cannot be edited');
select extensions.is((select count(*) from business_private.quotation_revisions),1::bigint,'authorized direct RLS shows own operational revision scope');
select extensions.lives_ok($$select public.create_quotation_draft('4b100000-0000-4000-8000-000000000001',(select id from ids))$$,'explicit new revision created');
select extensions.is(jsonb_array_length(public.list_request_quotations('4b100000-0000-4000-8000-000000000001')),2,'finalized revision retained in history');
select extensions.ok(not (select (content->>'teamAgreement')::boolean from business_private.quotation_revisions where state='draft'),'new revision requires fresh team confirmation');
select set_config('request.jwt.claims',pg_temp.claims(1,'aal1'),true);
select extensions.is((select count(*) from business_private.quotation_revisions),0::bigint,'direct AAL1 RLS hides quotations');
select set_config('request.jwt.claims',pg_temp.claims(2),true);
select extensions.is((select count(*) from business_private.quotation_revisions),0::bigint,'direct Content RLS hides quotations');
reset role;
update public.team_profiles set is_active=false where id='4b000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims',pg_temp.claims(1),true);
select extensions.throws_ok($$select public.list_request_quotations('4b100000-0000-4000-8000-000000000001')$$,'42501',null,'inactive operations cannot read quotations');
select extensions.is((select count(*) from business_private.quotation_revisions),0::bigint,'inactive operations direct RLS denied');
reset role;
select extensions.is((select count(*) from public.audit_logs where action='quotation.finalized' and resource_id=(select id::text from ids)),1::bigint,'exactly one finalization audit');
select extensions.throws_ok($$update business_private.quotation_revisions set content='{}' where id=(select id from ids)$$,'42501',null,'immutable snapshot trigger protects finalized rows even from accidental administrative updates');
select * from extensions.finish();rollback;
